package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.jsoup.Document;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class Node_siblingNodes_TriageGen2Test {

    @Test
    public void test_siblingNodes() {
        Document doc = Document.createShell("<html><body><p>Hello</p><p>World!</p></body></html>");
        Element p1 = doc.select("p").first();
        Element p2 = doc.select("p").get(1);

        assertEquals(1, p1.siblingNodes().size());
        assertEquals(p2, p1.siblingNodes().get(0));

        assertEquals(0, p2.siblingNodes().size());
    }

    @Test
    public void test_siblingNodes_EmptyDocument() {
        Document doc = Document.createShell("<html></html>");
        Element body = doc.select("body").first();

        assertEquals(0, body.siblingNodes().size());
    }

    @Test
    public void test_siblingNodes_NullParent() {
        assertThrows(NullPointerException.class, () -> new Node(null).siblingNodes());
    }

    @Test
    public void test_siblingNodes_NoSiblingNodes() {
        Document doc = Document.createShell("<html><body><p>Hello</p></body></html>");
        Element p1 = doc.select("p").first();

        assertEquals(0, p1.siblingNodes().size());
    }

    @Test
    public void test_siblingNodes_SingleChild() {
        Document doc = Document.createShell("<html><body><p>Hello</p></body></html>");
        Element body = doc.select("body").first();

        assertEquals(1, body.siblingNodes().size());
    }

    @Test
    public void test_siblingNodes_NoChildren() {
        Document doc = Document.createShell("<html><body></body></html>");
        Element body = doc.select("body").first();

        assertEquals(0, body.siblingNodes().size());
    }

    @Test
    public void test_siblingNodes_OneSiblingNode() {
        Document doc = Document.createShell("<html><body><p>Hello</p><p>World!</p></body></html>");
        Element p1 = doc.select("p").first();
        Element p2 = doc.select("p").get(1);

        assertEquals(1, p1.siblingNodes().size());
        assertEquals(p2, p1.siblingNodes().get(0));
    }

    @Test
    public void test_siblingNodes_MultipleSiblingNodes() {
        Document doc = Document.createShell("<html><body><p>Hello</p><p>World!</p><p>Foo!</p></body></html>");
        Element p1 = doc.select("p").first();
        Element p2 = doc.select("p").get(1);
        Element p3 = doc.select("p").get(2);

        assertEquals(2, p1.siblingNodes().size());
        assertEquals(p2, p1.siblingNodes().get(0));
        assertEquals(p3, p1.siblingNodes().get(1));
    }

    @Test
    public void test_siblingNodes_SiblingNodesWithChildren() {
        Document doc = Document.createShell("<html><body><p>Hello</p><p>World!</p><p>Foo!</p></body></html>");
        Element p1 = doc.select("p").first();
        Element p2 = doc.select("p").get(1);
        Element p3 = doc.select("p").get(2);

        assertEquals(2, p1.siblingNodes().size());
        assertEquals(p2, p1.siblingNodes().get(0));
        assertEquals(p3, p1.siblingNodes().get(1));
    }

    @Test
    public void test_siblingNodes_SiblingNodesWithChildrenAndAttr() {
        Document doc = Document.createShell("<html><body><p id=\"hello\">Hello</p><p id=\"world\">World!</p><p id=\"foo\">Foo!</p></body></html>");
        Element p1 = doc.select("p").first();
        Element p2 = doc.select("p").get(1);
        Element p3 = doc.select("p").get(2);

        assertEquals(2, p1.siblingNodes().size());
        assertEquals(p2, p1.siblingNodes().get(0));
        assertEquals(p3, p1.siblingNodes().get(1));
    }

    @Test
    public void test_siblingNodes_SiblingNodesEmpty() {
        Document doc = Document.createShell("<html><body><p>Hello</p></body></html>");
        Element p1 = doc.select("p").first();

        assertEquals(0, p1.siblingNodes().size());
    }
}
